		from, err := time.Parse(time.RFC3339, fromText)
		if err != nil {
			writeJobError(c, errTimeWindowInvalid)
			return
		}
		to, err := time.Parse(time.RFC3339, toText)
		if err != nil {
			writeJobError(c, errTimeWindowInvalid)
			return
		}
		if !from.Before(to) {
			writeJobError(c, errTimeWindowInvalid)
			return
		}

